/**
 * The demo catalog: invented artists and albums whose audio is generated by
 * `tone.ts` and whose sleeves are generated by `cover.ts` (docs/demo-mode.md).
 *
 * One source for every demo surface — the product tour's server, the demo
 * acquisition addon, and the future static demo — so they all show the same
 * library. Names are invented; any resemblance to a real act is coincidence.
 *
 * Two pools: `library` albums are on disk before anything starts; `acquirable`
 * albums exist only at the demo source, so the acquire flow always has something
 * real to find. A pool-`acquirable` album shares an artist with a library one on
 * purpose: it lands next to an album the viewer has already seen.
 *
 * Every album has at least {@link DEMO_MIN_ALBUM_TRACKS} tracks: the scanner's
 * heuristic files anything at or under `EP_MAX_TRACKS` (6) as an EP, and an EP
 * is missing from the Albums grid the tour opens on.
 */
import type { CoverMotif } from './cover.js';
import { toneSpec, type DemoGenre, type ToneSpec } from './tone.js';

export interface DemoAlbum {
  artist: string;
  title: string;
  year: number;
  genre: DemoGenre;
  pool: 'library' | 'acquirable';
  cover: CoverMotif;
  tracks: readonly string[];
}

/** One more than the scanner's `EP_MAX_TRACKS`. */
export const DEMO_MIN_ALBUM_TRACKS = 7;

