export interface DemoTrack {
  artist: string;
  album: string;
  title: string;
  trackNumber: number;
  totalTracks: number;
  year: number;
  genre: DemoGenre;
  /** Stable per track; the tone and every derived value come from it. */
  seed: string;
  tone: ToneSpec;
}

export function demoTracks(album: DemoAlbum): DemoTrack[] {
  return album.tracks.map((title, i) => {
    const seed = `${album.artist}\u0000${album.title}\u0000${title}`;
    return {
      artist: album.artist,
      album: album.title,
      title,
      trackNumber: i + 1,
      totalTracks: album.tracks.length,
      year: album.year,
      genre: album.genre,
      seed,
      tone: toneSpec(seed, album.genre),
    };
  });
}

/** Filesystem- and URL-safe slug, ASCII only ("Orbit Café" → "orbit-cafe"). */
export function demoSlug(text: string): string {
  return text
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

/** The demo song that carries synced lyrics: the title track of the acquirable album. */
export const DEMO_LYRICS_TRACK = { artist: 'Marlowe Vance', title: 'Paper Satellites' } as const;

const DEMO_LYRICS_LINES = [
  'Folded the evening into a paper plane',
  'Sent it up past the streetlights and the rain',
  'Every window hums a different song',
  'I keep the static, it keeps me company',
  'Paper satellites, circling the town',
  'Little lights that never quite come down',
  'Tune me in, I am somewhere on the dial',
  'Hold the signal, stay a little while',
  'Paper satellites, drifting out of view',
  'Every orbit brings me back to you',
];

/**
 * The demo lyrics as LRC, one line every two bars after the intro, so the
 * karaoke highlight moves in time with the rendered tempo instead of drifting.
 */
export function demoLyricsLrc(spec: ToneSpec): string {
  const secPerBar = (4 * 60) / spec.bpm;
  return DEMO_LYRICS_LINES.map((line, i) => {
    const t = (2 + i * 2) * secPerBar;
    const mm = String(Math.floor(t / 60)).padStart(2, '0');
    const ss = (t % 60).toFixed(2).padStart(5, '0');
    return `[${mm}:${ss}]${line}`;
  }).join('\n');
}

export function demoLyricsPlain(): string {
  return DEMO_LYRICS_LINES.join('\n');
}
